:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #173b35;
  background: #edf3ed;
}

* { box-sizing: border-box; }
body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  padding: 36px 16px;
  display: grid;
  place-items: center;
  background-color: #edf3ed;
  background-image: linear-gradient(135deg, #e1eee4 25%, transparent 25%), linear-gradient(225deg, #e1eee4 25%, transparent 25%), linear-gradient(45deg, #e1eee4 25%, transparent 25%), linear-gradient(315deg, #e1eee4 25%, #edf3ed 25%);
  background-position: 12px 0, 12px 0, 0 0, 0 0;
  background-size: 24px 24px;
}
.card {
  width: min(100%, 480px);
  padding: clamp(24px, 7vw, 40px);
  border: 2px solid #173b35;
  border-radius: 18px;
  background: #fffdf7;
  box-shadow: 8px 8px 0 #173b35;
}
.heading { text-align: center; }
.pixel-mark {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  margin: 0 auto 16px;
  border: 2px solid #173b35;
  border-radius: 12px;
  color: #fffdf7;
  background: #e6754c;
  font-size: 27px;
}
.eyebrow { margin: 0 0 6px; color: #477269; font-size: .8rem; font-weight: 800; letter-spacing: .14em; }
h1 { margin: 0; font-size: clamp(1.7rem, 7vw, 2.2rem); line-height: 1.15; }
.intro { max-width: 340px; margin: 12px auto 28px; color: #526c65; line-height: 1.5; }
form { display: grid; gap: 18px; }
.field label { display: block; margin-bottom: 7px; font-weight: 700; }
.input-wrap { display: flex; align-items: center; gap: 10px; min-height: 54px; padding: 0 15px; border: 2px solid #b7cbc1; border-radius: 10px; background: #fff; }
.input-wrap:focus-within { border-color: #267563; box-shadow: 0 0 0 3px #cce6d9; }
.input-wrap span { color: #477269; font-weight: 700; }
input { width: 100%; min-width: 0; border: 0; outline: 0; color: #173b35; background: transparent; font: inherit; font-size: 1.1rem; }
input::placeholder { color: #91a39b; }
button { min-height: 54px; margin-top: 4px; padding: 12px 18px; display: flex; align-items: center; justify-content: space-between; border: 2px solid #173b35; border-radius: 10px; color: #fffdf7; background: #267563; font: inherit; font-weight: 750; cursor: pointer; transition: background .15s, transform .15s, box-shadow .15s; }
button:hover { background: #1d5c4f; box-shadow: 0 3px 0 #173b35; transform: translateY(-2px); }
button:active { box-shadow: none; transform: translateY(1px); }
button:focus-visible { outline: 3px solid #e6754c; outline-offset: 3px; }
.message { min-height: 24px; margin: 18px 0 0; color: #526c65; text-align: center; }
.message.error { color: #a6402e; font-weight: 650; }
.result { margin-top: 20px; padding-top: 20px; border-top: 2px dashed #c7d8ce; }
[hidden] { display: none !important; }
.change-total { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.change-total span { color: #526c65; font-weight: 650; }
.change-total strong { color: #1d5c4f; font-size: 1.8rem; font-variant-numeric: tabular-nums; }
.breakdown-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-top: 20px; }
h2 { margin: 0; font-size: 1rem; }
#piece-count { color: #526c65; font-size: .9rem; }
.breakdown { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin: 12px 0 0; padding: 0; list-style: none; }
.breakdown li { display: flex; justify-content: space-between; gap: 8px; padding: 10px 12px; border-radius: 8px; color: #173b35; background: #e8f1e9; font-variant-numeric: tabular-nums; }
.breakdown li span:last-child { font-weight: 750; }
.empty-breakdown { grid-column: 1 / -1; color: #526c65 !important; }
footer { margin-top: 24px; padding-top: 16px; border-top: 1px solid #d8e3db; color: #668078; font-size: .8rem; line-height: 1.5; text-align: center; }
@media (max-width: 380px) { body { padding: 20px 12px; } .breakdown { grid-template-columns: 1fr; } }

const form = document.getElementById('change-form');
const priceInput = document.getElementById('price');
const paidInput = document.getElementById('paid');
const message = document.getElementById('message');
const result = document.getElementById('result');
const changeAmount = document.getElementById('change-amount');
const pieceCount = document.getElementById('piece-count');
const breakdown = document.getElementById('breakdown');

const denominations = [
  { cents: 2000, label: '$20' }, { cents: 1000, label: '$10' },
  { cents: 500, label: '$5' }, { cents: 200, label: '$2' },
  { cents: 100, label: '$1' }, { cents: 50, label: '50¢' },
  { cents: 20, label: '20¢' }, { cents: 10, label: '10¢' },
  { cents: 5, label: '5¢' }
];

function toCents(value) {
  return Math.round(Number(value) * 100);
}

function formatMoney(cents) {
  return `$${(cents / 100).toFixed(2)}`;
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const priceText = priceInput.value.trim();
  const paidText = paidInput.value.trim();
  const price = toCents(priceText);
  const paid = toCents(paidText);

  if (priceText === '' || paidText === '' || !Number.isFinite(price) || !Number.isFinite(paid) || price < 0 || paid < 0) {
    result.hidden = true;
    message.textContent = 'Enter valid, non-negative amounts in both fields.';
    message.classList.add('error');
    (priceText === '' || !Number.isFinite(price) || price < 0 ? priceInput : paidInput).focus();
    return;
  }
  if (paid < price) {
    result.hidden = true;
    message.textContent = 'Amount paid must be at least the price.';
    message.classList.add('error');
    paidInput.focus();
    return;
  }

  const change = paid - price;
  let remaining = change;
  let totalPieces = 0;
  breakdown.replaceChildren();
  for (const denomination of denominations) {
    const count = Math.floor(remaining / denomination.cents);
    remaining %= denomination.cents;
    if (count > 0) {
      totalPieces += count;
      const item = document.createElement('li');
      const name = document.createElement('span');
      const amount = document.createElement('span');
      name.textContent = denomination.label;
      amount.textContent = `× ${count}`;
      item.append(name, amount);
      breakdown.append(item);
    }
  }
  if (totalPieces === 0) {
    const item = document.createElement('li');
    item.className = 'empty-breakdown';
    item.textContent = 'Exact payment — no change due.';
    breakdown.append(item);
  }
  changeAmount.textContent = formatMoney(change);
  pieceCount.textContent = `${totalPieces} ${totalPieces === 1 ? 'piece' : 'pieces'}`;
  result.hidden = false;
  message.textContent = 'Change calculated.';
  message.classList.remove('error');
});
